//
// Cron expressions, evaluated (grammar 13.4, PRD resolved q78, Decision D162).
//
// The scheduler `./sources.ts` runs under `serve` asks this module one
// question per `schedule` trigger: when does this expression next fire, in this
// timezone, after this instant? It is byte-identical in every project this
// compiler release builds, like `./cel.ts`, and for the same reason it has **no
// imports**: the shared conformance corpus (`tests/fixtures/cron-conformance/`
// in the compiler's repository) runs against this file and against the
// compiler's own evaluator (`compose_core::cron`), and a module that pulled in
// the runtime would make that corpus a test of everything the runtime imports.
//
// # The grammar
//
// Five fields separated by whitespace — minute, hour, day of the month, month,
// day of the week. Each is a list of entries separated by `,`; an entry is `*`,
// a value, a range `a-b` (both ends included, smaller first), or a step `*/n`
// or `a-b/n` with `n >= 1`. Minutes run 0-59, hours 0-23, days of the month
// 1-31, months 1-12 or `JAN`-`DEC`, days of the week 0-7 or `SUN`-`SAT` with
// both 0 and 7 Sunday; names are three letters in any case, and only those two
// fields take them. `validate` refuses everything else (`invalid-cron`), so a
// composition this project was built from has nothing here to refuse — the
// refusals below are the same sentences, for the corpus and for a hand-edited
// project.
//
// **The day rule is POSIX's.** A field is restricted unless it is exactly `*`.
// When both day fields are restricted a day matches if either does; when one
// is, it alone decides.
//
// # Time
//
// An expression is matched against the **wall clock** of the trigger's zone,
// minute by minute, and fires at the instant that clock shows a matching
// minute. A wall-clock time daylight saving skips fires at the first instant
// after the gap — the transition itself, where several skipped times collapse
// into one firing — and one it repeats fires once, at its first occurrence.
//
// Zones are `Intl`'s, which carries the IANA database in both runtimes a
// generated project runs under: no timezone library, and no file of rules this
// project would have to keep current.

/** Why an expression cannot be evaluated, in the sentence `validate` uses. */
export class CronError extends Error {
  constructor(message: string) {
    super(message);
    this.name = "CronError";
  }
}

/** A parsed expression: one set of values per field, as bits. */
export interface Cron {
  readonly minutes: bigint;
  readonly hours: bigint;
  readonly days: bigint;
  readonly months: bigint;
  readonly weekdays: bigint;
  readonly daysRestricted: boolean;
  readonly weekdaysRestricted: boolean;
}

/** A UTC offset source: seconds east of UTC in force at an instant (seconds). */
export interface Zone {
  readonly name: string;
  offsetAt(instant: number): number;
}

interface Field {
  readonly name: string;
  readonly min: number;
  readonly max: number;
  readonly names: readonly string[];
}

const MONTH_NAMES = ["JAN", "FEB", "MAR", "APR", "MAY", "JUN", "JUL", "AUG", "SEP", "OCT", "NOV", "DEC"];
const WEEKDAY_NAMES = ["SUN", "MON", "TUE", "WED", "THU", "FRI", "SAT"];

const FIELDS: readonly Field[] = [
  { name: "minute", min: 0, max: 59, names: [] },
  { name: "hour", min: 0, max: 23, names: [] },
  { name: "day-of-month", min: 1, max: 31, names: [] },
  { name: "month", min: 1, max: 12, names: MONTH_NAMES },
  { name: "day-of-week", min: 0, max: 7, names: WEEKDAY_NAMES },
];

/**
 * How many days ahead [`nextAfter`] looks before answering that there is no
 * next tick: nine years, past the longest run without a February 29th (2096 to
 * 2104), which is the longest gap an expression `validate` accepts can have.
 */
export const HORIZON_DAYS = 366 * 9;

/** A sentinel for a run of digits too long to be in any field's range. */
const TOO_LONG = 0xffffffff;

/**
 * The characters that separate a cron expression's fields: ASCII whitespace,
 * exactly the set Rust's `split_ascii_whitespace` splits on in
 * `compose_core::cron` — space, tab, line feed, form feed and carriage return.
 * Not `\s`, which takes in the Unicode spaces too, and not quite the set
 * `split_whitespace` reads (that one has U+0085, which `\s` does not): two
 * readers of "whitespace" are two readings of the expression, and `validate`
 * would pass what `serve` could not evaluate.
 */
const FIELD_SEPARATOR = /[ \t\n\f\r]+/;

/** Parse grammar 13.4's five-field expression, or throw a [`CronError`]. */
export function parseCron(text: string): Cron {
  const parts = text.split(FIELD_SEPARATOR).filter((part) => part !== "");
  if (parts.length !== 5) {
    throw new CronError(`a cron expression has 5 fields, and this one has ${parts.length}`);
  }
  const sets: bigint[] = [];
  for (let index = 0; index < 5; index += 1) {
    const part = parts[index] as string;
    const field = FIELDS[index] as Field;
    try {
      sets.push(parseField(part, field));
    } catch (problem) {
      throw new CronError(`the ${field.name} field \`${part}\` ${(problem as Error).message}`);
    }
  }
  const dow = sets[4] as bigint;
  const cron: Cron = {
    minutes: sets[0] as bigint,
    hours: sets[1] as bigint,
    days: sets[2] as bigint,
    months: sets[3] as bigint,
    // Sunday is both 0 and 7; the evaluator reads 0.
    weekdays: (dow | (dow >> 7n)) & 0x7fn,
    daysRestricted: parts[2] !== "*",
    weekdaysRestricted: parts[4] !== "*",
  };
  if (cron.daysRestricted && !cron.weekdaysRestricted && !someMonthHasADay(cron)) {
    throw new CronError(
      `never fires: the day-of-month field \`${parts[2]}\` names no day that a month in the month field \`${parts[3]}\` has`,
    );
  }
  return cron;
}

function bit(set: bigint, value: number): boolean {
  return (set & (1n << BigInt(value))) !== 0n;
}

function longestMonth(month: number): number {
  if (month === 2) return 29;
  return month === 4 || month === 6 || month === 9 || month === 11 ? 30 : 31;
}

function someMonthHasADay(cron: Cron): boolean {
  for (let month = 1; month <= 12; month += 1) {
    if (!bit(cron.months, month)) continue;
    for (let day = 1; day <= longestMonth(month); day += 1) {
      if (bit(cron.days, day)) return true;
    }
  }
  return false;
}

/** A decimal number of at most four digits, [`TOO_LONG`] past that, or `undefined`. */
function numberOf(text: string): number | undefined {
  if (text === "" || !/^[0-9]+$/.test(text)) return undefined;
  if (text.length > 4) return TOO_LONG;
  return Number(text);
}

function valueOf(text: string, field: Field): number {
  if (text === "") throw new Error("is missing a value on one side of a `-`");
  const n = numberOf(text);
  if (n !== undefined) {
    if (n < field.min || n > field.max) {
      const shown = n === TOO_LONG ? text : String(n);
      throw new Error(`names ${shown}, outside ${field.min}-${field.max}`);
    }
    return n;
  }
  if (/^[A-Za-z]+$/.test(text)) {
    if (field.names.length === 0) {
      throw new Error(`names \`${text}\`, and only the month and day-of-week fields take names`);
    }
    const index = field.names.indexOf(text.toUpperCase());
    if (index >= 0) return field.min + index;
    throw new Error(`names \`${text}\`, which is not one of ${field.names.join(", ")}`);
  }
  throw new Error(`holds \`${text}\`, which is not a number, a name, \`*\`, a range or a step`);
}

function parseField(text: string, field: Field): bigint {
  let set = 0n;
  for (const entry of text.split(",")) {
    if (entry === "") throw new Error("has an empty entry in its list");
    const slash = entry.indexOf("/");
    const range = slash < 0 ? entry : entry.slice(0, slash);
    const written = slash < 0 ? undefined : entry.slice(slash + 1);
    let step = 1;
    if (written !== undefined) {
      const n = numberOf(written);
      if (n === undefined) throw new Error(`steps by \`${written}\`, which is not a whole number`);
      if (n === 0) throw new Error("steps by 0, and a step is at least 1");
      step = n;
    }
    let low: number;
    let high: number;
    if (range === "*") {
      low = field.min;
      high = field.max;
    } else {
      const dash = range.indexOf("-");
      if (dash >= 0) {
        low = valueOf(range.slice(0, dash), field);
        high = valueOf(range.slice(dash + 1), field);
        if (low > high) {
          throw new Error(`has the range \`${range}\`, which runs backwards: write the smaller end first`);
        }
      } else {
        const single = valueOf(range, field);
        if (written !== undefined) {
          throw new Error(
            `steps the single value \`${range}\`: a step needs a range, so write \`${range}-${field.max}/${step}\` or \`*/${step}\``,
          );
        }
        low = single;
        high = single;
      }
    }
    for (let at = low; at <= high; at += step) set |= 1n << BigInt(at);
  }
  return set;
}

// ---------------------------------------------------------------------------
// The calendar
// ---------------------------------------------------------------------------

/** Floor division, for the day arithmetic below. */
function div(a: number, b: number): number {
  return Math.floor(a / b);
}

/** Non-negative remainder. */
function mod(a: number, b: number): number {
  return ((a % b) + b) % b;
}

/** The civil date of a day count since the epoch (Howard Hinnant's algorithm). */
export function civilFromDays(days: number): [number, number, number] {
  const z = days + 719468;
  const era = div(z, 146097);
  const doe = mod(z, 146097);
  const yoe = div(doe - div(doe, 1460) + div(doe, 36524) - div(doe, 146096), 365);
  const doy = doe - (365 * yoe + div(yoe, 4) - div(yoe, 100));
  const mp = div(5 * doy + 2, 153);
  const day = doy - div(153 * mp + 2, 5) + 1;
  const month = mp < 10 ? mp + 3 : mp - 9;
  const year = yoe + era * 400 + (month <= 2 ? 1 : 0);
  return [year, month, day];
}

function dayMatches(cron: Cron, day: number): boolean {
  const [, month, date] = civilFromDays(day);
  if (!bit(cron.months, month)) return false;
  const byDate = bit(cron.days, date);
  const byWeekday = bit(cron.weekdays, mod(day + 4, 7));
  if (cron.daysRestricted && cron.weekdaysRestricted) return byDate || byWeekday;
  if (cron.daysRestricted) return byDate;
  if (cron.weekdaysRestricted) return byWeekday;
  return true;
}

/**
 * The instant (seconds) a wall-clock minute `wall` (local seconds since the
 * epoch) fires at in `zone`: its earliest occurrence, or for a time a gap
 * skips, the transition that skipped it. The candidates are the compiler's,
 * asked in the same order (`compose_core::cron`).
 */
function fireInstant(wall: number, zone: Zone): number {
  const candidates = [zone.offsetAt(wall - 86400), zone.offsetAt(wall), zone.offsetAt(wall + 86400)];
  let earliest: number | undefined;
  for (const offset of candidates) {
    const instant = wall - offset;
    if (zone.offsetAt(instant) === offset) {
      earliest = earliest === undefined ? instant : Math.min(earliest, instant);
    }
  }
  if (earliest !== undefined) return earliest;
  const smaller = Math.min(...candidates);
  const larger = Math.max(...candidates);
  let before = wall - larger;
  let after = wall - smaller;
  const held = zone.offsetAt(before);
  while (after - before > 1) {
    const middle = before + div(after - before, 2);
    if (zone.offsetAt(middle) === held) before = middle;
    else after = middle;
  }
  return after;
}

/**
 * The first instant **strictly after** `from` (epoch milliseconds) at which
 * `cron` fires in `zone`, or `undefined` when it has none inside
 * [`HORIZON_DAYS`].
 */
export function nextAfter(cron: Cron, from: number, zone: Zone): number | undefined {
  const fromSeconds = div(from, 1000);
  const local = fromSeconds + zone.offsetAt(fromSeconds);
  const startMinute = div(local, 60);
  const startDay = div(startMinute, 1440);
  const startOfDay = mod(startMinute, 1440);
  for (let day = startDay; day < startDay + HORIZON_DAYS; day += 1) {
    if (!dayMatches(cron, day)) continue;
    const firstHour = day === startDay ? div(startOfDay, 60) : 0;
    const firstMinute = day === startDay ? mod(startOfDay, 60) : 0;
    for (let hour = firstHour; hour < 24; hour += 1) {
      if (!bit(cron.hours, hour)) continue;
      const fromMinute = day === startDay && hour === firstHour ? firstMinute : 0;
      for (let minute = fromMinute; minute < 60; minute += 1) {
        if (!bit(cron.minutes, minute)) continue;
        const fires = fireInstant((day * 1440 + hour * 60 + minute) * 60, zone) * 1000;
        if (fires > from) return fires;
      }
    }
  }
  return undefined;
}

// ---------------------------------------------------------------------------
// Zones
// ---------------------------------------------------------------------------

/** The zone a `schedule` trigger with no `timezone:` is evaluated in. */
export const UTC: Zone = { name: "UTC", offsetAt: () => 0 };

/**
 * The zone `name` names, read through `Intl` — or a thrown `RangeError` where
 * the runtime's timezone database does not know it, which `serve` reports at
 * start naming the trigger.
 */
export function zoneOf(name: string): Zone {
  if (name === "UTC") return UTC;
  const format = new Intl.DateTimeFormat("en-US", {
    timeZone: name,
    hourCycle: "h23",
    year: "numeric",
    month: "numeric",
    day: "numeric",
    hour: "numeric",
    minute: "numeric",
    second: "numeric",
    era: "short",
  });
  const cache = new Map<number, number>();
  return {
    name,
    offsetAt(instant: number): number {
      const held = cache.get(instant);
      if (held !== undefined) return held;
      const parts: Record<string, string> = {};
      for (const part of format.formatToParts(new Date(instant * 1000))) parts[part.type] = part.value;
      let year = Number(parts["year"]);
      if (parts["era"] === "BC" || parts["era"] === "B") year = 1 - year;
      const local =
        Date.UTC(
          year,
          Number(parts["month"]) - 1,
          Number(parts["day"]),
          Number(parts["hour"]),
          Number(parts["minute"]),
          Number(parts["second"]),
        ) / 1000;
      // `Date.UTC` maps a two-digit year into the 1900s; the years a schedule
      // reaches are four digits, so nothing here needs `setUTCFullYear`.
      const offset = local - instant;
      if (cache.size > 4096) cache.clear();
      cache.set(instant, offset);
      return offset;
    },
  };
}

function pad(value: number, width: number): string {
  return String(value).padStart(width, "0");
}

/**
 * An instant (epoch milliseconds) as RFC 3339 in `zone`: the zone's wall clock
 * and its numeric offset, `+00:00` for UTC — what `payload.scheduled_at` is
 * (grammar 13.4).
 */
export function render(instant: number, zone: Zone): string {
  const seconds = div(instant, 1000);
  const offset = zone.offsetAt(seconds);
  const local = seconds + offset;
  const [year, month, day] = civilFromDays(div(local, 86400));
  const ofDay = mod(local, 86400);
  const magnitude = Math.abs(offset);
  return `${pad(year, 4)}-${pad(month, 2)}-${pad(day, 2)}T${pad(div(ofDay, 3600), 2)}:${pad(div(mod(ofDay, 3600), 60), 2)}:${pad(mod(ofDay, 60), 2)}${offset < 0 ? "-" : "+"}${pad(div(magnitude, 3600), 2)}:${pad(div(mod(magnitude, 3600), 60), 2)}`;
}
